#!/usr/bin/env python3
"""Console Checkers (Draughts): 8x8 board, two players, mandatory jumps, kinging."""

EMPTY = "."


def new_board():
    g = [[EMPTY] * 8 for _ in range(8)]
    for r in range(8):
        for c in range(8):
            if (r + c) % 2 == 1:
                if r < 3:
                    g[r][c] = "b"
                elif r > 4:
                    g[r][c] = "r"
    return g


def owner(p):
    if p in ("r", "R"):
        return "r"
    if p in ("b", "B"):
        return "b"
